begin;
drop table if exists public.contributions cascade; drop table if exists public.fund_settings cascade; drop table if exists public.profiles cascade; drop table if exists public.villages cascade;
drop function if exists public.is_super_admin() cascade; drop function if exists public.is_village_admin(uuid) cascade; drop function if exists public.update_updated_at() cascade;
create table public.villages(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null,village_id uuid references public.villages(id) on delete set null,full_name text,mobile text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint profiles_role_check check(role in('admin','super_admin')),constraint super_admin_village_check check(role='admin' or village_id is null));
create table public.fund_settings(id uuid primary key default gen_random_uuid(),village_id uuid not null unique references public.villages(id) on delete cascade,village_name text,monthly_amount numeric(12,2),upi_id text,upi_name text,upi_instructions text,bank_account_holder text,bank_name text,account_number text,ifsc_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.contributions(id uuid primary key default gen_random_uuid(),village_id uuid not null references public.villages(id) on delete cascade,contributor_name text not null,amount numeric(12,2) not null,transaction_date timestamptz not null default now(),payment_status text not null default 'pending',phonepe_transaction_id text,phonepe_order_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint contribution_amount_check check(amount>0),constraint contribution_status_check check(payment_status in('pending','success','failed')));
create index contributions_village_id_idx on public.contributions(village_id); create index contributions_status_idx on public.contributions(payment_status); create index contributions_transaction_date_idx on public.contributions(transaction_date desc); create index profiles_village_id_idx on public.profiles(village_id);
create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='super_admin');$$;
create or replace function public.is_village_admin(requested_village_id uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin' and village_id=requested_village_id);$$;
revoke all on function public.is_super_admin() from public; grant execute on function public.is_super_admin() to authenticated; revoke all on function public.is_village_admin(uuid) from public; grant execute on function public.is_village_admin(uuid) to authenticated;
alter table public.villages enable row level security; alter table public.profiles enable row level security; alter table public.fund_settings enable row level security; alter table public.contributions enable row level security;
create policy "Public can view active villages" on public.villages for select to anon,authenticated using(is_active=true); create policy "Super admin can manage villages" on public.villages for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
create policy "Users can view own profile" on public.profiles for select to authenticated using(id=auth.uid()); create policy "Super admin can view all profiles" on public.profiles for select to authenticated using(public.is_super_admin()); create policy "Super admin can manage profiles" on public.profiles for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
create policy "Public can view active village settings" on public.fund_settings for select to anon,authenticated using(exists(select 1 from public.villages v where v.id=fund_settings.village_id and v.is_active=true)); create policy "Super admin can manage fund settings" on public.fund_settings for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin()); create policy "Village admin can manage own settings" on public.fund_settings for update to authenticated using(public.is_village_admin(village_id)) with check(public.is_village_admin(village_id));
create policy "Public can view successful contributions" on public.contributions for select to anon,authenticated using(payment_status='success' and exists(select 1 from public.villages v where v.id=contributions.village_id and v.is_active=true)); create policy "Village admin can view own contributions" on public.contributions for select to authenticated using(public.is_village_admin(village_id)); create policy "Super admin can manage contributions" on public.contributions for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
create or replace function public.update_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now(); return new; end;$$;
create trigger villages_updated_at before update on public.villages for each row execute function public.update_updated_at(); create trigger profiles_updated_at before update on public.profiles for each row execute function public.update_updated_at(); create trigger fund_settings_updated_at before update on public.fund_settings for each row execute function public.update_updated_at(); create trigger contributions_updated_at before update on public.contributions for each row execute function public.update_updated_at();
commit;
